document.addEventListener('DOMContentLoaded', () => {
    // Initialize Lucide Icons
    if (typeof lucide !== 'undefined') {
        lucide.createIcons();
    }

    // --- Theme Switcher Logic ---
    const themeToggleBtn = document.getElementById('theme-toggle');
    const currentTheme = localStorage.getItem('theme') || 'dark';

    // Apply the saved theme on load
    if (currentTheme === 'light') {
        document.documentElement.setAttribute('data-theme', 'light');
    } else {
        document.documentElement.removeAttribute('data-theme');
    }

    themeToggleBtn.addEventListener('click', () => {
        let theme = document.documentElement.getAttribute('data-theme');
        if (theme === 'light') {
            document.documentElement.removeAttribute('data-theme');
            localStorage.setItem('theme', 'dark');
        } else {
            document.documentElement.setAttribute('data-theme', 'light');
            localStorage.setItem('theme', 'light');
        }
    });

    // --- Mobile Navigation Menu ---
    const mobileToggleBtn = document.getElementById('mobile-toggle');
    const navMenu = document.getElementById('nav-menu');

    function setMobileMenuIcon(iconName) {
        if (!mobileToggleBtn) return;
        mobileToggleBtn.innerHTML = `<i data-lucide="${iconName}"></i>`;
        if (typeof lucide !== 'undefined') {
            lucide.createIcons();
        }
    }

    if (mobileToggleBtn && navMenu) {
        mobileToggleBtn.addEventListener('click', () => {
            navMenu.classList.toggle('active');
            const isActive = navMenu.classList.contains('active');
            setMobileMenuIcon(isActive ? 'x' : 'menu');
            document.body.style.overflow = isActive ? 'hidden' : '';
        });

        // Close mobile menu when a link is clicked
        const navLinksList = document.querySelectorAll('.nav-link');
        navLinksList.forEach(link => {
            link.addEventListener('click', () => {
                if (navMenu.classList.contains('active')) {
                    navMenu.classList.remove('active');
                    setMobileMenuIcon('menu');
                    document.body.style.overflow = '';
                }
            });
        });

        // Close mobile menu on desktop resize
        window.addEventListener('resize', () => {
            if (window.innerWidth > 768 && navMenu.classList.contains('active')) {
                navMenu.classList.remove('active');
                setMobileMenuIcon('menu');
                document.body.style.overflow = '';
            }
        });

        // Close on Escape key
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && navMenu.classList.contains('active')) {
                navMenu.classList.remove('active');
                setMobileMenuIcon('menu');
                document.body.style.overflow = '';
            }
        });
    }

    // --- Typing Animation ---
    const typingTextSpan = document.getElementById('typing-text');
    const phrases = [
        "I craft scalable full-stack experiences.",
        "I build robust backend applications.",
        "I design beautiful user interfaces.",
        "I secure and maintain enterprise databases."
    ];
    let phraseIndex = 0;
    let charIndex = 0;
    let isDeleting = false;
    let typingSpeed = 100;

    function type() {
        const currentPhrase = phrases[phraseIndex];
        
        if (isDeleting) {
            // Delete characters
            typingTextSpan.textContent = currentPhrase.substring(0, charIndex - 1);
            charIndex--;
            typingSpeed = 50; // faster deleting
        } else {
            // Type characters
            typingTextSpan.textContent = currentPhrase.substring(0, charIndex + 1);
            charIndex++;
            typingSpeed = 100; // normal typing
        }

        // Handle word completion
        if (!isDeleting && charIndex === currentPhrase.length) {
            // Pause at the end of the phrase
            typingSpeed = 2000;
            isDeleting = true;
        } else if (isDeleting && charIndex === 0) {
            isDeleting = false;
            // Move to next phrase
            phraseIndex = (phraseIndex + 1) % phrases.length;
            typingSpeed = 500; // Pause before typing next word
        }

        setTimeout(type, typingSpeed);
    }

    // Start typing animation
    if (typingTextSpan) {
        type();
    }

    // --- Scroll Effects (Header and Back to Top) ---
    const navbar = document.getElementById('navbar');
    const backToTopBtn = document.getElementById('back-to-top');

    window.addEventListener('scroll', () => {
        if (window.scrollY > 50) {
            navbar.classList.add('scrolled');
        } else {
            navbar.classList.remove('scrolled');
        }

        if (window.scrollY > 500) {
            backToTopBtn.classList.add('show');
        } else {
            backToTopBtn.classList.remove('show');
        }
    });

    backToTopBtn.addEventListener('click', () => {
        window.scrollTo({
            top: 0,
            behavior: 'smooth'
        });
    });

    // --- Intersection Observer for Scroll Animations ---
    const revealElements = document.querySelectorAll('.reveal');
    const skillBars = document.querySelectorAll('.skill-bar-fill');

    const observerOptions = {
        threshold: 0.15,
        rootMargin: '0px 0px -50px 0px'
    };

    const revealObserver = new IntersectionObserver((entries, observer) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.classList.add('active');
                
                // If it's the skills section, animate progress bars
                if (entry.target.id === 'skills') {
                    animateSkillBars();
                }
                
                observer.unobserve(entry.target);
            }
        });
    }, observerOptions);

    revealElements.forEach(element => {
        revealObserver.observe(element);
    });

    const skillsSection = document.getElementById('skills');
    if (skillsSection) {
        revealObserver.observe(skillsSection);
    }

    function animateSkillBars() {
        skillBars.forEach(bar => {
            const percentage = bar.getAttribute('data-percent');
            bar.style.width = percentage;
        });
    }

    // --- Active Nav Link Highlight on Scroll (Scrollspy) ---
    const sectionsList = document.querySelectorAll('section');
    
    function scrollspy() {
        const scrollPosition = window.scrollY || document.documentElement.scrollTop;
        const offset = 120; // Navigation bar height offset
        
        let activeSection = null;
        
        sectionsList.forEach(section => {
            const sectionTop = section.offsetTop - offset;
            const sectionHeight = section.offsetHeight;
            
            if (scrollPosition >= sectionTop && scrollPosition < sectionTop + sectionHeight) {
                activeSection = section;
            }
        });
        
        // Edge case: if reached bottom of the page, activate the last section (Contact)
        if ((window.innerHeight + window.scrollY) >= document.documentElement.scrollHeight - 50) {
            activeSection = document.getElementById('contact');
        }
        
        if (activeSection) {
            const activeId = activeSection.getAttribute('id');
            navLinksList.forEach(link => {
                link.classList.remove('active');
                if (link.getAttribute('href') === `#${activeId}`) {
                    link.classList.add('active');
                }
            });
        }
    }
    
    window.addEventListener('scroll', scrollspy);
    window.addEventListener('load', scrollspy);

    // --- Contact Form Submission Handler (Sends to premkardani2006@gmail.com) ---
    const contactForm = document.getElementById('contact-form');
    if (contactForm) {
        contactForm.addEventListener('submit', async (e) => {
            e.preventDefault();

            // Get form values
            const name = document.getElementById('name').value.trim();
            const email = document.getElementById('email').value.trim();
            const subject = document.getElementById('subject').value.trim();
            const message = document.getElementById('message').value.trim();

            const submitBtn = contactForm.querySelector('button[type="submit"]');
            const originalBtnHtml = submitBtn.innerHTML;

            submitBtn.disabled = true;
            submitBtn.style.opacity = '0.7';
            submitBtn.innerHTML = 'Sending Message... <i data-lucide="loader-2" class="animate-spin"></i>';
            if (typeof lucide !== 'undefined') {
                lucide.createIcons();
            }

            // Web3Forms submission
            const accessKeyInput = document.getElementById('web3forms-access-key');
            const accessKey = accessKeyInput ? accessKeyInput.value.trim() : '';

            let sentDirectly = false;

            if (accessKey && accessKey !== 'YOUR_WEB3FORMS_ACCESS_KEY') {
                try {
                    const formData = new FormData(contactForm);
                    const response = await fetch('https://api.web3forms.com/submit', {
                        method: 'POST',
                        body: formData
                    });

                    const data = await response.json();
                    if (data.success) {
                        sentDirectly = true;
                    }
                } catch (err) {
                    console.warn('API submission failed, falling back to direct mailbox opener:', err);
                }
            }

            if (sentDirectly) {
                submitBtn.innerHTML = 'Message Sent! <i data-lucide="check"></i>';
                submitBtn.style.background = 'linear-gradient(135deg, #10b981 0%, #059669 100%)';
                if (typeof lucide !== 'undefined') {
                    lucide.createIcons();
                }
                contactForm.reset();

                setTimeout(() => {
                    submitBtn.disabled = false;
                    submitBtn.style.opacity = '1';
                    submitBtn.style.background = '';
                    submitBtn.innerHTML = originalBtnHtml;
                    if (typeof lucide !== 'undefined') {
                        lucide.createIcons();
                    }
                }, 3500);
            } else {
                // Direct Mailbox Opener (Opens user's default mailbox with their own account as sender and yours as receiver)
                submitBtn.innerHTML = 'Opening Mailbox... <i data-lucide="mail"></i>';
                if (typeof lucide !== 'undefined') {
                    lucide.createIcons();
                }

                const targetEmail = 'premkardani2006@gmail.com';
                const emailSubject = encodeURIComponent(subject ? `[Portfolio] ${subject}` : `[Portfolio Message from ${name}]`);
                const emailBody = encodeURIComponent(
                    `Hello Prem,\n\nName: ${name}\nEmail: ${email}\nSubject: ${subject}\n\nMessage:\n${message}\n\n---\nSent from your portfolio contact form`
                );

                window.location.href = `mailto:${targetEmail}?subject=${emailSubject}&body=${emailBody}`;

                setTimeout(() => {
                    submitBtn.innerHTML = 'Draft Opened in Mailbox! <i data-lucide="check"></i>';
                    submitBtn.style.background = 'linear-gradient(135deg, #10b981 0%, #059669 100%)';
                    if (typeof lucide !== 'undefined') {
                        lucide.createIcons();
                    }
                    contactForm.reset();

                    setTimeout(() => {
                        submitBtn.disabled = false;
                        submitBtn.style.opacity = '1';
                        submitBtn.style.background = '';
                        submitBtn.innerHTML = originalBtnHtml;
                        if (typeof lucide !== 'undefined') {
                            lucide.createIcons();
                        }
                    }, 3500);
                }, 1000);
            }
        });
    }
});

// --- Direct CV Download Handler (Works on file:/// and web servers without opening in tab) ---
const resumeBase64 = "";

function downloadResume(e) {
    if (e && e.preventDefault) e.preventDefault();
    const btn = document.getElementById("download-cv-btn");
    const originalHtml = btn ? btn.innerHTML : "";
    if (btn) {
        btn.style.pointerEvents = "none";
        btn.innerHTML = 'Downloading... <i data-lucide="loader-2" class="animate-spin"></i>';
        if (typeof lucide !== "undefined") lucide.createIcons();
    }

    try {
        const byteCharacters = atob(resumeBase64);
        const byteNumbers = new Uint8Array(byteCharacters.length);
        for (let i = 0; i < byteCharacters.length; i++) {
            byteNumbers[i] = byteCharacters.charCodeAt(i);
        }
        const blob = new Blob([byteNumbers], { type: "application/octet-stream" });
        const blobUrl = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.style.display = "none";
        link.href = blobUrl;
        link.download = "prem resume.pdf";
        document.body.appendChild(link);
        link.click();
        setTimeout(() => {
            document.body.removeChild(link);
            URL.revokeObjectURL(blobUrl);
            if (btn) {
                btn.style.pointerEvents = "auto";
                btn.innerHTML = originalHtml;
                if (typeof lucide !== "undefined") lucide.createIcons();
            }
        }, 1000);
    } catch (err) {
        console.error("Download error:", err);
        if (btn) {
            btn.style.pointerEvents = "auto";
            btn.innerHTML = originalHtml;
            if (typeof lucide !== "undefined") lucide.createIcons();
        }
    }
}
window.downloadResume = downloadResume;

